package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.Caracteristica
import com.example.sgva.domain.ConfiguracionPonderaciones
import com.example.sgva.domain.ResultadoAutoevaluacion

/**
 * Módulo 4 — resultado de autoevaluación del programa (`DESIGN_SGVA.md` §0.1
 * "Reglas de cálculo del resultado de autoevaluación" y §2).
 *
 * Calcula, para un [programa] y un [periodo], el promedio por característica,
 * por factor y global del modelo institucional de 12 factores y 48
 * características, a partir de los `ResultadoEncuestaPregunta` y
 * `EvaluacionDocumental` ya registrados. El universo de factores y
 * características, y todos los pesos usados en la mezcla, provienen
 * exclusivamente de [configuracion]: este caso de uso no hardcodea ningún
 * peso ni ningún identificador de factor o característica.
 *
 * Aplica exactamente las reglas de `DESIGN_SGVA.md` §0.1, sin criterios
 * adicionales no documentados.
 */
class CalcularResultadoAutoevaluacionUseCase(
    private val repositorio: AcademicDataRepository,
    private val configuracion: ConfiguracionPonderaciones,
) {

    fun ejecutar(programa: String, periodo: String): ResultadoAutoevaluacion {
        val promediosEncuestaPorCaracteristica = repositorio.listarResultadosEncuestaPregunta()
            .filter { it.programa == programa && it.periodo == periodo }
            .groupBy { it.caracteristica }
            .mapValues { (_, resultados) -> promedioDeEncuesta(resultados.mapNotNull { it.promedio }) }

        val documentalPorCaracteristica = repositorio.listarEvaluacionesDocumentales()
            .filter { it.programa == programa && it.periodo == periodo }
            .associateBy { it.caracteristica }

        val promediosPorCaracteristica = configuracion.caracteristicas.associate { caracteristica ->
            caracteristica.id to promedioDeCaracteristica(
                resultadoEncuesta = promediosEncuestaPorCaracteristica[caracteristica.id],
                documental = documentalPorCaracteristica[caracteristica.id]?.calificacion,
            )
        }

        val promediosPorFactor = configuracion.pesosFactores.keys.associateWith { factor ->
            promedioPonderadoReponderado(
                caracteristicasDelFactor(factor).mapNotNull { caracteristica ->
                    promediosPorCaracteristica[caracteristica.id]?.let { it to caracteristica.ponderacion }
                },
            )
        }

        val promedioGlobal = promedioPonderadoReponderado(
            configuracion.pesosFactores.mapNotNull { (factor, peso) ->
                promediosPorFactor[factor]?.let { it to peso }
            },
        )

        return ResultadoAutoevaluacion(
            programa = programa,
            periodo = periodo,
            promediosPorCaracteristica = promediosPorCaracteristica,
            promediosPorFactor = promediosPorFactor,
            promedioGlobal = promedioGlobal,
        )
    }

    private fun caracteristicasDelFactor(factor: String): List<Caracteristica> =
        configuracion.caracteristicas.filter { it.factor == factor }

    /**
     * Regla 1 de §0.1: promedio de los promedios de las preguntas con valor
     * de la característica, o ausente si ninguna pregunta tiene valor.
     */
    private fun promedioDeEncuesta(promedios: List<Double>): Double? =
        if (promedios.isEmpty()) null else promedios.average()

    /**
     * Regla 2 de §0.1: mezcla documental/encuesta de una característica, el
     * valor documental completo si la encuesta está ausente, o ausente si no
     * hay evaluación documental.
     */
    private fun promedioDeCaracteristica(resultadoEncuesta: Double?, documental: Double?): Double? = when {
        documental == null -> null
        resultadoEncuesta == null -> documental
        else -> documental * configuracion.pesoDocumental + resultadoEncuesta * configuracion.pesoEncuestas
    }

    /**
     * Reglas 3 y 4 de §0.1: promedio ponderado de los valores presentes,
     * reponderando sus pesos de configuración entre sí. Ausente si no hay
     * ningún valor presente, o si los pesos de los valores presentes suman
     * cero (no hay ninguna base de reponderación válida).
     */
    private fun promedioPonderadoReponderado(valoresConPeso: List<Pair<Double, Double>>): Double? {
        if (valoresConPeso.isEmpty()) return null
        val sumaPesos = valoresConPeso.sumOf { it.second }
        if (sumaPesos == 0.0) return null
        return valoresConPeso.sumOf { (valor, peso) -> valor * peso } / sumaPesos
    }
}

package com.example.sgva.application

import com.example.sgva.domain.Caracteristica
import com.example.sgva.domain.ConfiguracionPonderaciones
import com.example.sgva.domain.EvaluacionDocumental
import com.example.sgva.domain.ResultadoEncuestaPregunta
import com.example.sgva.domain.TipoEstamento
import com.example.sgva.usecases.CalcularResultadoAutoevaluacionUseCase
import org.junit.jupiter.api.Test
import kotlin.test.assertEquals
import kotlin.test.assertNull

/**
 * Verifica `CalcularResultadoAutoevaluacionUseCase` contra las reglas de
 * cálculo de `DESIGN_SGVA.md` §0.1, con un catálogo sintético de dos factores
 * (F1 con C1/C2, F2 con C3/C4) y una mezcla encuestas/documental de 40 %/60 %.
 * Los pesos no corresponden al modelo 2025 real: son datos de prueba para
 * aislar cada regla.
 */
class CalcularResultadoAutoevaluacionUseCaseTest {

    private val repositorio = RepositorioAcademicoFalso()

    private val configuracion = ConfiguracionPonderaciones(
        caracteristicas = listOf(
            Caracteristica(id = "C1", nombre = "Característica 1", factor = "F1", ponderacion = 0.5),
            Caracteristica(id = "C2", nombre = "Característica 2", factor = "F1", ponderacion = 0.5),
            Caracteristica(id = "C3", nombre = "Característica 3", factor = "F2", ponderacion = 0.3),
            Caracteristica(id = "C4", nombre = "Característica 4", factor = "F2", ponderacion = 0.7),
        ),
        pesosFactores = mapOf("F1" to 0.6, "F2" to 0.4),
        pesoEncuestas = 0.4,
        pesoDocumental = 0.6,
    )

    private val useCase = CalcularResultadoAutoevaluacionUseCase(repositorio, configuracion)

    private fun registrarPregunta(
        codigoPregunta: String,
        caracteristica: String,
        promedio: Double?,
    ) {
        repositorio.guardarResultadoEncuestaPregunta(
            ResultadoEncuestaPregunta(
                programa = "EGSTI",
                periodo = "20261",
                codigoPregunta = codigoPregunta,
                caracteristica = caracteristica,
                estamentos = setOf(TipoEstamento.ESTUDIANTE),
                promedio = promedio,
            ),
        )
    }

    private fun registrarDocumental(caracteristica: String, calificacion: Double) {
        repositorio.guardarEvaluacionDocumental(
            EvaluacionDocumental(
                programa = "EGSTI",
                caracteristica = caracteristica,
                periodo = "20261",
                calificacion = calificacion,
            ),
        )
    }

    @Test
    fun `el resultado de encuesta de una caracteristica es el promedio de los promedios de sus preguntas`() {
        registrarPregunta("A1", "C1", 3.0)
        registrarPregunta("A2", "C1", 5.0)
        registrarDocumental("C1", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // encuesta = (3.0 + 5.0) / 2 = 4.0; promedio = 4.0*0.6 + 4.0*0.4 = 4.0
        assertEquals(4.0, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `las preguntas con promedio null no cuentan en el resultado de encuesta`() {
        registrarPregunta("A1", "C1", 4.0)
        registrarPregunta("A2", "C1", null)
        registrarDocumental("C1", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // encuesta = 4.0 (la pregunta ausente no cuenta); promedio = 4.0*0.6 + 4.0*0.4 = 4.0
        assertEquals(4.0, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `una caracteristica sin ninguna pregunta con valor tiene resultado de encuesta ausente`() {
        registrarPregunta("A1", "C1", null)
        registrarDocumental("C1", 4.7)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // encuesta ausente -> el promedio es el valor documental completo, sin aplicar su peso de mezcla
        assertEquals(4.7, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `una caracteristica sin preguntas registradas tiene resultado de encuesta ausente`() {
        registrarDocumental("C1", 4.7)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertEquals(4.7, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `una caracteristica con encuesta y documental mezcla ambas fuentes con los pesos de la configuracion`() {
        registrarPregunta("A1", "C1", 2.0)
        registrarDocumental("C1", 5.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // documental 5.0 * 0.6 + encuesta 2.0 * 0.4 = 3.0 + 0.8 = 3.8
        assertEquals(3.8, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `una caracteristica sin evaluacion documental es ausente aunque tenga encuesta`() {
        registrarPregunta("A1", "C1", 5.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorCaracteristica["C1"])
    }

    @Test
    fun `una caracteristica sin ninguna fuente es ausente`() {
        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorCaracteristica["C1"])
    }

    @Test
    fun `el promedio de un factor reponderan los pesos de las caracteristicas presentes`() {
        // C1 (peso 0.5) ausente; solo C2 (peso 0.5) tiene documental.
        registrarDocumental("C2", 4.4)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorCaracteristica["C1"])
        // reponderado: solo C2 presente -> su peso se normaliza a 1.0, el promedio del factor es su propio valor
        assertEquals(4.4, resultado.promediosPorFactor["F1"]!!, 1e-9)
    }

    @Test
    fun `el promedio de un factor con todas sus caracteristicas presentes no cambia por la reponderacion`() {
        registrarDocumental("C1", 4.0)
        registrarDocumental("C2", 5.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // 4.0*0.5 + 5.0*0.5 = 4.5 (los pesos ya suman 1.0, reponderar no cambia nada)
        assertEquals(4.5, resultado.promediosPorFactor["F1"]!!, 1e-9)
    }

    @Test
    fun `un factor sin ninguna caracteristica calculable es ausente`() {
        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorFactor["F1"])
    }

    @Test
    fun `el promedio global reponderan los pesos de los factores presentes`() {
        // F1 (peso 0.6) ausente por completo; solo F2 (peso 0.4) tiene datos.
        registrarDocumental("C3", 4.0)
        registrarDocumental("C4", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorFactor["F1"])
        // reponderado: solo F2 presente -> su peso se normaliza a 1.0
        assertEquals(4.0, resultado.promedioGlobal!!, 1e-9)
    }

    @Test
    fun `el promedio global con todos los factores y caracteristicas presentes no cambia por la reponderacion`() {
        registrarDocumental("C1", 4.0)
        registrarDocumental("C2", 5.0)
        registrarDocumental("C3", 3.0)
        registrarDocumental("C4", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        val f1 = 4.0 * 0.5 + 5.0 * 0.5 // 4.5
        val f2 = 3.0 * 0.3 + 4.0 * 0.7 // 3.7
        val global = f1 * 0.6 + f2 * 0.4

        assertEquals(f1, resultado.promediosPorFactor["F1"]!!, 1e-9)
        assertEquals(f2, resultado.promediosPorFactor["F2"]!!, 1e-9)
        assertEquals(global, resultado.promedioGlobal!!, 1e-9)
    }

    @Test
    fun `el promedio global es ausente cuando ningun factor es calculable`() {
        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promedioGlobal)
    }

    @Test
    fun `el resultado conserva el catalogo completo de caracteristicas y factores aunque esten ausentes`() {
        registrarDocumental("C1", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertEquals(setOf("C1", "C2", "C3", "C4"), resultado.promediosPorCaracteristica.keys)
        assertEquals(setOf("F1", "F2"), resultado.promediosPorFactor.keys)
    }

    @Test
    fun `el resultado solo usa datos del programa y periodo consultados`() {
        registrarDocumental("C1", 4.0)
        repositorio.guardarEvaluacionDocumental(
            EvaluacionDocumental(programa = "OTRO-PROGRAMA", caracteristica = "C1", periodo = "20261", calificacion = 1.0),
        )
        repositorio.guardarEvaluacionDocumental(
            EvaluacionDocumental(programa = "EGSTI", caracteristica = "C1", periodo = "20252", calificacion = 1.0),
        )

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertEquals(4.0, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `el resultado expone el programa y periodo consultados`() {
        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertEquals("EGSTI", resultado.programa)
        assertEquals("20261", resultado.periodo)
    }
}

package com.example.sgva.infrastructure.configuracion

import com.example.sgva.domain.Caracteristica
import com.example.sgva.domain.ConfiguracionPonderaciones
import com.example.sgva.domain.FormatoArchivoInvalidoException
import de.siegmar.fastcsv.reader.CsvReader
import java.io.IOException
import java.nio.file.Files
import java.nio.file.NoSuchFileException
import java.nio.file.Path

/**
 * Carga [ConfiguracionPonderaciones] desde un archivo externo entregado por el
 * investigador (`DESIGN_SGVA.md` §4 "Carga de configuración de ponderaciones";
 * `CLAUDE.md` delega a Claude CLI el formato y la ubicación concretos). Nunca
 * contiene valores de peso hardcodeados: todos provienen del archivo leído.
 *
 * Formato esperado (encabezado exacto, en ese orden): `tipo,id,factor,nombre,ponderacion`.
 * Cada fila de datos es una de tres clases, según su columna `tipo`:
 *
 * - `FACTOR`: `id` es el identificador del factor; `ponderacion` es su peso
 *   dentro del global. Las columnas `factor` y `nombre` no se usan.
 * - `CARACTERISTICA`: `id`, `factor` y `nombre` alimentan directamente
 *   [Caracteristica]; `ponderacion` es su peso dentro de su factor.
 * - `MEZCLA`: `id` es `ENCUESTAS` o `DOCUMENTAL`; `ponderacion` es el peso de
 *   esa fuente en la mezcla de una característica. Ambas filas son
 *   obligatorias.
 *
 * No aplica ninguna validación de negocio propia (sumas de pesos, pesos no
 * negativos): construye [ConfiguracionPonderaciones] con los valores leídos y
 * deja que sea su propio `init` el que las aplique, para no duplicar esas
 * reglas. Cualquier problema de formato del archivo (columnas, filas, tipos o
 * archivo faltante) se reporta como [FormatoArchivoInvalidoException], con un
 * mensaje claro y sin recurrir a ningún valor por defecto.
 */
class CargadorConfiguracionPonderaciones {

    /** Lee el archivo en [ruta] del sistema de archivos y construye la configuración. */
    fun cargar(ruta: Path): ConfiguracionPonderaciones {
        val contenido = try {
            Files.readString(ruta)
        } catch (causa: NoSuchFileException) {
            throw FormatoArchivoInvalidoException("No se encontró el archivo de ponderaciones '$ruta'.", causa)
        } catch (causa: IOException) {
            throw FormatoArchivoInvalidoException("No se pudo leer el archivo de ponderaciones '$ruta'.", causa)
        }
        return parsear(contenido, ruta.toString())
    }

    /**
     * Construye la configuración a partir del [contenido] ya leído de un
     * archivo CSV. [origen] solo se usa para identificar el archivo en los
     * mensajes de error (ej. una ruta o un nombre de archivo).
     */
    fun parsear(contenido: String, origen: String): ConfiguracionPonderaciones {
        val filas = CsvReader.builder()
            .skipEmptyLines(true)
            .ofCsvRecord(contenido)
            .use { lector -> lector.map { it.fields } }

        if (filas.isEmpty()) {
            throw FormatoArchivoInvalidoException("El archivo de ponderaciones '$origen' no contiene ninguna fila.")
        }

        val encabezado = filas.first()
        if (encabezado != COLUMNAS_ESPERADAS) {
            throw FormatoArchivoInvalidoException(
                "El archivo de ponderaciones '$origen' debe tener las columnas " +
                    "${COLUMNAS_ESPERADAS.joinToString(",")}; encontradas: ${encabezado.joinToString(",")}.",
            )
        }

        val caracteristicas = mutableListOf<Caracteristica>()
        val pesosFactores = mutableMapOf<String, Double>()
        var pesoEncuestas: Double? = null
        var pesoDocumental: Double? = null

        filas.drop(1).forEachIndexed { indice, fila ->
            val numeroFila = indice + 2 // fila 1 es el encabezado
            if (fila.size != COLUMNAS_ESPERADAS.size) {
                throw FormatoArchivoInvalidoException(
                    "Archivo de ponderaciones '$origen', fila $numeroFila: se esperaban " +
                        "${COLUMNAS_ESPERADAS.size} columnas y se encontraron ${fila.size}.",
                )
            }

            val (tipo, id, factor, nombre, ponderacionTexto) = fila
            val ponderacion = parsearPonderacion(ponderacionTexto, origen, numeroFila)

            when (tipo.trim()) {
                "FACTOR" -> pesosFactores[id.trim()] = ponderacion
                "CARACTERISTICA" -> caracteristicas += Caracteristica(
                    id = id.trim(),
                    nombre = nombre.trim(),
                    factor = factor.trim(),
                    ponderacion = ponderacion,
                )
                "MEZCLA" -> when (id.trim()) {
                    "ENCUESTAS" -> pesoEncuestas = ponderacion
                    "DOCUMENTAL" -> pesoDocumental = ponderacion
                    else -> throw FormatoArchivoInvalidoException(
                        "Archivo de ponderaciones '$origen', fila $numeroFila: clave de mezcla desconocida " +
                            "'$id'; se esperaba 'ENCUESTAS' o 'DOCUMENTAL'.",
                    )
                }
                else -> throw FormatoArchivoInvalidoException(
                    "Archivo de ponderaciones '$origen', fila $numeroFila: tipo desconocido '$tipo'; " +
                        "se esperaba FACTOR, CARACTERISTICA o MEZCLA.",
                )
            }
        }

        if (pesoEncuestas == null || pesoDocumental == null) {
            throw FormatoArchivoInvalidoException(
                "El archivo de ponderaciones '$origen' debe incluir las filas MEZCLA,ENCUESTAS y MEZCLA,DOCUMENTAL.",
            )
        }

        return ConfiguracionPonderaciones(
            caracteristicas = caracteristicas,
            pesosFactores = pesosFactores,
            pesoEncuestas = pesoEncuestas,
            pesoDocumental = pesoDocumental,
        )
    }

    private fun parsearPonderacion(texto: String, origen: String, numeroFila: Int): Double =
        texto.trim().toDoubleOrNull() ?: throw FormatoArchivoInvalidoException(
            "Archivo de ponderaciones '$origen', fila $numeroFila: la ponderación '$texto' no es un número válido.",
        )

    companion object {
        private val COLUMNAS_ESPERADAS = listOf("tipo", "id", "factor", "nombre", "ponderacion")
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.DocumentParserPort
import com.example.sgva.domain.ResultadoEncuestaPregunta

/**
 * Módulo 4 — carga masiva de resultados de encuesta por pregunta desde un
 * archivo CSV o Excel (`DESIGN_SGVA.md` §2), reutilizando la normalización y
 * el protocolo de validación en origen ya existentes para las demás
 * entidades (`DESIGN_SGVA.md` §5). Registra cada resultado reutilizando
 * [RegistrarResultadoEncuestaPreguntaUseCase].
 */
class ProcesarResultadosEncuestaPreguntaUseCase(
    parsers: List<DocumentParserPort>,
    private val registrarResultadoEncuestaPregunta: RegistrarResultadoEncuestaPreguntaUseCase,
) : ProcesarArchivoUseCase<ResultadoEncuestaPregunta>(parsers) {

    override fun extraer(
        parser: DocumentParserPort,
        nombreArchivo: String,
        contenido: ByteArray,
    ): List<ResultadoEncuestaPregunta> = parser.extraerResultadosEncuestaPregunta(nombreArchivo, contenido)

    override fun idDe(entidad: ResultadoEncuestaPregunta): String =
        "${entidad.programa}/${entidad.periodo}/${entidad.codigoPregunta}"

    override fun registrar(entidad: ResultadoEncuestaPregunta) {
        registrarResultadoEncuestaPregunta.ejecutar(entidad)
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.DocumentParserPort
import com.example.sgva.domain.EvaluacionDocumental

/**
 * Módulo 4 — carga masiva de evaluaciones documentales desde un archivo CSV o
 * Excel (`DESIGN_SGVA.md` §2), reutilizando la normalización y el protocolo
 * de validación en origen ya existentes para las demás entidades
 * (`DESIGN_SGVA.md` §5). Registra cada evaluación reutilizando
 * [RegistrarEvaluacionDocumentalUseCase].
 */
class ProcesarEvaluacionesDocumentalesUseCase(
    parsers: List<DocumentParserPort>,
    private val registrarEvaluacionDocumental: RegistrarEvaluacionDocumentalUseCase,
) : ProcesarArchivoUseCase<EvaluacionDocumental>(parsers) {

    override fun extraer(
        parser: DocumentParserPort,
        nombreArchivo: String,
        contenido: ByteArray,
    ): List<EvaluacionDocumental> = parser.extraerEvaluacionesDocumentales(nombreArchivo, contenido)

    override fun idDe(entidad: EvaluacionDocumental): String =
        "${entidad.programa}/${entidad.periodo}/${entidad.caracteristica}"

    override fun registrar(entidad: EvaluacionDocumental) {
        registrarEvaluacionDocumental.ejecutar(entidad)
    }
}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.FormatoArchivoInvalidoException
import de.siegmar.fastcsv.reader.CsvReader
import org.springframework.stereotype.Component
import java.nio.ByteBuffer
import java.nio.charset.CharacterCodingException
import java.nio.charset.CodingErrorAction
import java.nio.charset.StandardCharsets

/**
 * Adaptador de [com.example.sgva.domain.DocumentParserPort] para archivos `.csv`,
 * implementado sobre FastCSV (`DESIGN_SGVA.md` §4, adaptador «OpenCsvParser» del
 * diseño; se usa FastCSV por ser una dependencia sin transitivas y gestionable
 * dentro del stack de Spring Boot 4).
 *
 * Soporta tanto los archivos que ya se cargan hoy (UTF-8, separador `,`) como
 * el formato real de las áreas (`DESIGN_SGVA.md` §4, "Robustez de lectura V5"):
 * separador `;`, coma decimal, `N/A` como dato faltante, codificación
 * ISO-8859-1 (Latin-1) y filas de título antes del encabezado. La detección
 * de encabezado y la normalización de valores las aplica [ParserDocumentalBase]
 * a través de los mapeadores.
 */
@Component
internal class CsvDocumentParser : ParserDocumentalBase() {

    override fun soporta(nombreArchivo: String): Boolean = extension(nombreArchivo) == "csv"

    override fun leerTabla(contenido: ByteArray): TablaCruda {
        val texto = decodificar(contenido)
        val separador = detectarSeparador(texto)

        val registros = CsvReader.builder()
            .fieldSeparator(separador)
            .skipEmptyLines(true)
            .ofCsvRecord(texto)
            .use { lector -> lector.map { it.fields } }
            .filter { fila -> fila.any { it.isNotBlank() } }

        if (registros.isEmpty()) {
            throw FormatoArchivoInvalidoException("El archivo CSV no contiene ninguna fila.")
        }

        return TablaCruda(filas = registros)
    }

    /**
     * Los archivos que ya se cargan hoy están en UTF-8; las áreas entregan los
     * suyos en ISO-8859-1 (Latin-1). Se intenta UTF-8 estricto primero porque
     * Latin-1 nunca falla al decodificar (cubre los 256 valores de byte) y por
     * tanto no sirve para detectar el formato por sí solo.
     */
    private fun decodificar(contenido: ByteArray): String {
        val decodificadorUtf8 = StandardCharsets.UTF_8.newDecoder()
            .onMalformedInput(CodingErrorAction.REPORT)
            .onUnmappableCharacter(CodingErrorAction.REPORT)
        return try {
            decodificadorUtf8.decode(ByteBuffer.wrap(contenido)).toString()
        } catch (_: CharacterCodingException) {
            String(contenido, StandardCharsets.ISO_8859_1)
        }
    }

    /**
     * Los archivos que ya se cargan hoy separan columnas con `,`; los de las
     * áreas usan `;` como separador de columnas y `,` como separador decimal.
     * Se elige el símbolo que aparece más veces en el archivo.
     */
    private fun detectarSeparador(texto: String): Char =
        if (texto.count { it == ';' } > texto.count { it == ',' }) ';' else ','

    private fun extension(nombreArchivo: String): String =
        nombreArchivo.substringAfterLast('.', "").lowercase()
}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.Docente
import com.example.sgva.domain.DocumentParserPort
import com.example.sgva.domain.Estudiante
import com.example.sgva.domain.EvaluacionDocumental
import com.example.sgva.domain.FormatoArchivoInvalidoException
import com.example.sgva.domain.ResultadoEncuestaPregunta
import com.example.sgva.domain.RespuestaEncuesta

/**
 * Base común de los adaptadores de [DocumentParserPort]. Concentra el
 * *Protocolo de Validación en Origen* (`DESIGN_SGVA.md` §5):
 *
 *  1. Cada adaptador concreto solo se encarga de leer el archivo a una
 *     [TablaCruda] (todas sus filas de texto, sin distinguir encabezado) según
 *     su formato físico.
 *  2. Esta base localiza la fila de encabezado y verifica que estén todas las
 *     columnas obligatorias de la entidad, descartando las filas de título
 *     que la preceden.
 *  3. Mapea y normaliza fila por fila; cualquier fallo se envuelve en
 *     [FormatoArchivoInvalidoException] indicando el archivo y la fila, sin dejar
 *     escapar excepciones técnicas de la librería de parseo.
 */
internal abstract class ParserDocumentalBase : DocumentParserPort {

    /**
     * Lee el archivo a una tabla de texto. Puede lanzar excepciones técnicas de
     * la librería subyacente: [transformar] las traduce a excepción controlada.
     */
    protected abstract fun leerTabla(contenido: ByteArray): TablaCruda

    final override fun extraerEstudiantes(nombreArchivo: String, contenido: ByteArray): List<Estudiante> =
        transformar(nombreArchivo, contenido, MapeadorEstudiante)

    final override fun extraerDocentes(nombreArchivo: String, contenido: ByteArray): List<Docente> =
        transformar(nombreArchivo, contenido, MapeadorDocente)

    final override fun extraerRespuestasEncuestas(nombreArchivo: String, contenido: ByteArray): List<RespuestaEncuesta> =
        transformar(nombreArchivo, contenido, MapeadorRespuestaEncuesta)

    final override fun extraerResultadosEncuestaPregunta(
        nombreArchivo: String,
        contenido: ByteArray,
    ): List<ResultadoEncuestaPregunta> = transformar(nombreArchivo, contenido, MapeadorResultadoEncuestaPregunta)

    final override fun extraerEvaluacionesDocumentales(
        nombreArchivo: String,
        contenido: ByteArray,
    ): List<EvaluacionDocumental> = transformar(nombreArchivo, contenido, MapeadorEvaluacionDocumental)

    private fun <T> transformar(
        nombreArchivo: String,
        contenido: ByteArray,
        mapeador: MapeadorEntidad<T>,
    ): List<T> {
        val tabla = leerTablaControlada(nombreArchivo, contenido)
        val indiceEncabezado = localizarEncabezado(nombreArchivo, tabla.filas, mapeador.columnasObligatorias)
        val encabezados = tabla.filas[indiceEncabezado].map(String::trim)

        return tabla.filas.drop(indiceEncabezado + 1).mapIndexed { posicion, valores ->
            // +1 por el encabezado, +1 para numeración en base 1; indiceEncabezado desplaza
            // la cuenta cuando el archivo trae filas de título antes del encabezado.
            val numeroFila = indiceEncabezado + posicion + 2
            val fila = encabezados.zip(valores).toMap()
            try {
                mapeador.mapear(fila)
            } catch (datoInvalido: IllegalArgumentException) {
                // Cubre también NumberFormatException (subtipo) y las excepciones de dominio.
                throw FormatoArchivoInvalidoException(
                    "Archivo '$nombreArchivo', fila $numeroFila: ${datoInvalido.message}",
                    datoInvalido,
                )
            }
        }
    }

    private fun leerTablaControlada(nombreArchivo: String, contenido: ByteArray): TablaCruda =
        try {
            leerTabla(contenido)
        } catch (formatoInvalido: FormatoArchivoInvalidoException) {
            throw formatoInvalido
        } catch (falloTecnico: Exception) {
            throw FormatoArchivoInvalidoException(
                "No se pudo leer el archivo '$nombreArchivo': ${falloTecnico.message}",
                falloTecnico,
            )
        }

    /**
     * Localiza la fila de encabezado como la primera que contiene todas las
     * columnas obligatorias de la entidad; las filas anteriores son títulos
     * del área y se descartan (`DESIGN_SGVA.md` §4, "Robustez de lectura V5").
     * Si ninguna fila las contiene todas, se señalan como faltantes las que
     * no aparecen en la fila con más coincidencias.
     */
    private fun localizarEncabezado(
        nombreArchivo: String,
        filas: List<List<String>>,
        obligatorias: Set<String>,
    ): Int {
        val coincidencias = filas.map { fila -> fila.map(String::trim).toSet().intersect(obligatorias) }
        val indiceCandidato = coincidencias.indices.maxBy { coincidencias[it].size }

        if (coincidencias[indiceCandidato].size < obligatorias.size) {
            val faltantes = (obligatorias - coincidencias[indiceCandidato]).sorted()
            throw FormatoArchivoInvalidoException(
                "Al archivo '$nombreArchivo' le faltan columnas obligatorias: ${faltantes.joinToString(", ")}.",
            )
        }
        return indiceCandidato
    }
}

package com.example.sgva.domain

/**
 * Puerto de salida (Outbound/Driven Port) para persistir y recuperar las
 * entidades de dominio ya validadas (`DESIGN_SGVA.md` §3).
 *
 * El dominio declara la interfaz; la tecnología concreta vive en
 * `infrastructure` y nunca al revés (Inversión de Dependencia). En esta versión
 * el único adaptador es en memoria; un futuro adaptador Spring Data debe poder
 * sustituirlo sin tocar el dominio ni los casos de uso.
 *
 * Toda entidad que entra o sale de este puerto es válida por construcción: sus
 * invariantes se verifican en el bloque `init` de [Estudiante] y [Docente], no
 * aquí ni en los adaptadores (`DESIGN_SGVA.md` §0.1).
 *
 * El identificador (`id`) es la clave de identidad de cada entidad. Este puerto
 * solo almacena y consulta; la regla de aplicación "un `id` no puede
 * registrarse dos veces" la aplican los casos de uso de registro.
 */
interface AcademicDataRepository {

    /** Persiste [estudiante] indexado por su `id` y lo devuelve sin cambios. */
    fun guardarEstudiante(estudiante: Estudiante): Estudiante

    /** Devuelve el estudiante con [id], o `null` si no hay ninguno registrado. */
    fun buscarEstudiantePorId(id: String): Estudiante?

    /** Devuelve todos los estudiantes registrados, en orden de inserción. */
    fun listarEstudiantes(): List<Estudiante>

    /** Persiste [docente] indexado por su `id` y lo devuelve sin cambios. */
    fun guardarDocente(docente: Docente): Docente

    /** Devuelve el docente con [id], o `null` si no hay ninguno registrado. */
    fun buscarDocentePorId(id: String): Docente?

    /** Devuelve todos los docentes registrados, en orden de inserción. */
    fun listarDocentes(): List<Docente>

    /** Persiste [respuesta] indexada por su `id` y la devuelve sin cambios. */
    fun guardarRespuestaEncuesta(respuesta: RespuestaEncuesta): RespuestaEncuesta

    /** Devuelve la respuesta de encuesta con [id], o `null` si no hay ninguna registrada. */
    fun buscarRespuestaEncuestaPorId(id: String): RespuestaEncuesta?

    /** Devuelve todas las respuestas de encuesta registradas, en orden de inserción. */
    fun listarRespuestasEncuesta(): List<RespuestaEncuesta>

    /** Persiste [resultado] y lo devuelve sin cambios. */
    fun guardarResultadoEncuestaPregunta(resultado: ResultadoEncuestaPregunta): ResultadoEncuestaPregunta

    /**
     * Devuelve el resultado de encuesta por pregunta cuya clave natural es
     * ([programa], [periodo], [codigoPregunta]), o `null` si no hay ninguno registrado.
     */
    fun buscarResultadoEncuestaPregunta(
        programa: String,
        periodo: String,
        codigoPregunta: String,
    ): ResultadoEncuestaPregunta?

    /** Devuelve todos los resultados de encuesta por pregunta registrados, en orden de inserción. */
    fun listarResultadosEncuestaPregunta(): List<ResultadoEncuestaPregunta>

    /** Persiste [evaluacion] y la devuelve sin cambios. */
    fun guardarEvaluacionDocumental(evaluacion: EvaluacionDocumental): EvaluacionDocumental

    /**
     * Devuelve la evaluación documental cuya clave natural es ([programa],
     * [periodo], [caracteristica]), o `null` si no hay ninguna registrada.
     */
    fun buscarEvaluacionDocumental(
        programa: String,
        periodo: String,
        caracteristica: String,
    ): EvaluacionDocumental?

    /** Devuelve todas las evaluaciones documentales registradas, en orden de inserción. */
    fun listarEvaluacionesDocumentales(): List<EvaluacionDocumental>
}

package com.example.sgva.application

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.Docente
import com.example.sgva.domain.Estudiante
import com.example.sgva.domain.EvaluacionDocumental
import com.example.sgva.domain.ResultadoEncuestaPregunta
import com.example.sgva.domain.RespuestaEncuesta

/**
 * Doble de prueba en memoria del puerto [AcademicDataRepository]. Permite
 * ejercitar los casos de uso sin depender del adaptador de infraestructura.
 * Pública (no `internal`) para poder exponerse como bean de Spring en las
 * pruebas de integración de `infrastructure.web` (`ConfiguracionCasosDeUsoDePrueba`).
 */
class RepositorioAcademicoFalso : AcademicDataRepository {

    private val estudiantes = LinkedHashMap<String, Estudiante>()
    private val docentes = LinkedHashMap<String, Docente>()
    private val respuestasEncuesta = LinkedHashMap<String, RespuestaEncuesta>()
    private val resultadosEncuestaPregunta = LinkedHashMap<String, ResultadoEncuestaPregunta>()
    private val evaluacionesDocumentales = LinkedHashMap<String, EvaluacionDocumental>()

    override fun guardarEstudiante(estudiante: Estudiante): Estudiante {
        estudiantes[estudiante.id] = estudiante
        return estudiante
    }

    override fun buscarEstudiantePorId(id: String): Estudiante? = estudiantes[id]

    override fun listarEstudiantes(): List<Estudiante> = estudiantes.values.toList()

    override fun guardarDocente(docente: Docente): Docente {
        docentes[docente.id] = docente
        return docente
    }

    override fun buscarDocentePorId(id: String): Docente? = docentes[id]

    override fun listarDocentes(): List<Docente> = docentes.values.toList()

    override fun guardarRespuestaEncuesta(respuesta: RespuestaEncuesta): RespuestaEncuesta {
        respuestasEncuesta[respuesta.id] = respuesta
        return respuesta
    }

    override fun buscarRespuestaEncuestaPorId(id: String): RespuestaEncuesta? = respuestasEncuesta[id]

    override fun listarRespuestasEncuesta(): List<RespuestaEncuesta> = respuestasEncuesta.values.toList()

    override fun guardarResultadoEncuestaPregunta(resultado: ResultadoEncuestaPregunta): ResultadoEncuestaPregunta {
        resultadosEncuestaPregunta[claveDe(resultado.programa, resultado.periodo, resultado.codigoPregunta)] =
            resultado
        return resultado
    }

    override fun buscarResultadoEncuestaPregunta(
        programa: String,
        periodo: String,
        codigoPregunta: String,
    ): ResultadoEncuestaPregunta? = resultadosEncuestaPregunta[claveDe(programa, periodo, codigoPregunta)]

    override fun listarResultadosEncuestaPregunta(): List<ResultadoEncuestaPregunta> =
        resultadosEncuestaPregunta.values.toList()

    private fun claveDe(programa: String, periodo: String, codigoPregunta: String): String =
        "$programa|$periodo|$codigoPregunta"

    override fun guardarEvaluacionDocumental(evaluacion: EvaluacionDocumental): EvaluacionDocumental {
        evaluacionesDocumentales[claveDe(evaluacion.programa, evaluacion.periodo, evaluacion.caracteristica)] =
            evaluacion
        return evaluacion
    }

    override fun buscarEvaluacionDocumental(
        programa: String,
        periodo: String,
        caracteristica: String,
    ): EvaluacionDocumental? = evaluacionesDocumentales[claveDe(programa, periodo, caracteristica)]

    override fun listarEvaluacionesDocumentales(): List<EvaluacionDocumental> =
        evaluacionesDocumentales.values.toList()

    /** Vacía los cinco almacenes; útil para reutilizar la misma instancia entre pruebas. */
    fun limpiar() {
        estudiantes.clear()
        docentes.clear()
        respuestasEncuesta.clear()
        resultadosEncuestaPregunta.clear()
        evaluacionesDocumentales.clear()
    }
}

